const menu=document.querySelector('.menu-toggle');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));document.querySelector('nav').classList.toggle('open',open)});document.querySelectorAll('nav details').forEach(d=>d.addEventListener('toggle',()=>{if(d.open)document.querySelectorAll('nav details').forEach(o=>{if(o!==d)o.open=false})}));document.addEventListener('click',e=>{if(!e.target.closest('nav details'))document.querySelectorAll('nav details').forEach(d=>d.open=false);if(e.target.closest('nav a')){document.querySelector('nav').classList.remove('open');menu.setAttribute('aria-expanded','false')}});document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelectorAll('nav details').forEach(d=>d.open=false);document.querySelector('nav').classList.remove('open');menu.setAttribute('aria-expanded','false')}});
const audiences={customer:['Поставьте задачу и подтвердите результат','Вы выбираете исполнителя и принимаете работу. Платформа формирует документы и проводит выплату по согласованным условиям.'],worker:['Согласуйте условия и выполните работу','Находите заказчиков, договаривайтесь о задаче и выполняйте её. Документы и выплата после подтверждения результата — в одном кабинете.']};const tabs=[...document.querySelectorAll('[data-audience]')];function setTab(tab){tabs.forEach(t=>{t.setAttribute('aria-selected',String(t===tab));t.tabIndex=t===tab?0:-1});const p=document.querySelector('#service-panel'),content=audiences[tab.dataset.audience];p.setAttribute('aria-labelledby',tab.id);p.querySelector('h3').textContent=content[0];p.querySelector('p').textContent=content[1]}tabs.forEach((t,i)=>{t.addEventListener('click',()=>setTab(t));t.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const next=tabs[e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+1)%tabs.length];setTab(next);next.focus()}})});
